const ALL_SPOTS = AREAS.flatMap(a => a.spots);
const D = k => (S && S.decor ? S.decor[k] || 0 : 0);
const done = k => !!(S && S.areaDone && S.areaDone[k]);
const areaCount = a => a.spots.reduce((s, d) => s + D(d.k), 0);
const areaFull = a => areaCount(a) >= a.spots.length * 2;
const evOn = () => { if (S && S.settings && S.settings.evPreview) return true; const d = new Date(), mo = d.getMonth() + 1; return mo === 12 || (mo === 1 && d.getDate() <= 7); };
const areaOpen = i => AREAS[i].event ? (evOn() || areaCount(AREAS[i]) > 0) : (i === 0 || areaFull(AREAS[i - 1])) && chOpen(AREAS[i].ch || 1);
const curOf = a => a.cur === 'snow' ? 'snow' : 'stars';
const MC = () => S.onEv && S.ev ? S.ev.chains : S.chains;
const maxE = () => MAX_E + 10 * D('terrace') + (done('flower') ? 20 : 0) + (done('chestnut') ? 20 : 0) + (done('hotteok') ? 20 : 0) + (APP ? 10 * D('lamp') : 0);
const regenMs = () => Math.round((REGEN_MS - 10000 * D('planter')) * (done('bath') ? .8 : 1) * (done('camp') ? .9 : 1) * (done('cocoa') ? .9 : 1));
// 에너지 100을 50코인부터 팔고, 하루 안에서 살 때마다 두 배 (50 → 100 → … → 12800, 9번째부터는 그대로)
const energyPrice = n => Math.round(50 * 2 ** Math.min(n, 8) * (1 - 0.1 * D('wall')));
// 행운 뽑기: 코인을 쓰는 곳. 값은 레벨 비례, 횟수 제한 없음
const ALBUM_ICON = () => (WHEEL && WHEEL.album) ? `<img src="${WHEEL.album}" alt="" draggable="false">` : `<svg viewBox="0 0 48 48" stroke="#5b3a32" stroke-width="3" stroke-linejoin="round" stroke-linecap="round"><rect x="8" y="7" width="32" height="35" rx="5" fill="#ff9db0"/><path d="M14 7v35" fill="none"/><rect x="18" y="13" width="17" height="14" rx="3" fill="#fff6ea"/><path d="M20 25l4-5 3 3 2-2 4 4" fill="none" stroke-width="2.2"/><circle cx="30" cy="17.5" r="1.8" fill="#ffd75a" stroke-width="1.6"/><path d="M26.5 35.5c-2-1.6-3.5-2.8-3.5-4.4 0-1.2.9-2 2-2 .7 0 1.2.3 1.5.8.3-.5.8-.8 1.5-.8 1.1 0 2 .8 2 2 0 1.6-1.5 2.8-3.5 4.4z" fill="#fff" stroke-width="2"/></svg>`;
const DRAW_ICON = () => (WHEEL && WHEEL.draw && WHEEL.draw[0] !== '@' ? `<img src="${WHEEL.draw}" alt="" draggable="false">` : iconBag(3));
const drawPrice = () => Math.round(30 + 6 * (S ? S.level : 1));
const DRAW = [['e', 20, 35], ['e', 50, 14], ['e', 100, 4], ['cut', 1, 17], ['up', 1, 8], ['bag', 1, 7], ['bag', 2, 4], ['bag', 3, 1], ['s', 2, 8], ['s', 5, 2], ['box', 1, 8], ['box', 2, 2]];
const coinsOf = od => Math.round(od.coins * (1 + 0.1 * D('sign') + (done('station') ? 0.2 : 0) + (done('maple') ? 0.2 : 0) + (done('cablecar') ? 0.2 : 0) + (done('yacht') ? 0.05 : 0)));
const xpOf = od => Math.round(od.xp * (1 + 0.1 * D('awning') + (done('book') ? 0.2 : 0) + (done('library') ? 0.2 : 0) + (done('musichall') ? 0.2 : 0)));
const starsOf = od => od.req.reduce((s, r) => s + (r.l <= 3 ? 1 : r.l <= 5 ? 2 : r.l <= 7 ? 3 : 4), 0) + (done('park') ? 1 : 0) + (done('dock') ? 1 : 0) + (done('skate') ? 1 : 0);
const stOpen = (ch, j) => { const g = stGapOf(ch, j); if (g < 0) return true; const A = chLots(ch)[g]; return !!A && areaOpen(AREAS.indexOf(A)); };
const chLots = ch => AREAS.filter(A => !A.event && (A.ch || 1) === ch);
function stGapOf(ch, j) { const n = STREET[ch].length, gaps = chLots(ch).length + 1; return Math.floor(j * gaps / n) - 1; }
const canDecor = () => AREAS.some((a, i) => areaOpen(i) && a.spots.some(d => D(d.k) < 2 && S[curOf(a)] >= d.costs[D(d.k)]))
  || CHS.some(ch => chOpen(ch) && STREET[ch].some((_, j) => SL(stKey(ch, j)) < 3 && stOpen(ch, j) && S.stars >= stCost(ch, j, SL(stKey(ch, j)))));
const pick = a => a[Math.floor(Math.random() * a.length)];
const today = () => new Date().toDateString();
const rc = i => [Math.floor(i / COLS), i % COLS];
