function renderStore() {
  const box = $('.mc-store'); if (!box || !S) return;
  const sx = box.querySelector('.mc-sts')?.scrollLeft || 0;
  let h = '<div class="mc-stt">';
  TK.forEach((k, n) => { const c = S.tools[k] || 0; h += `<div class="c tl ${c ? '' : 'zero'}" data-i="${TLB + n}" title="${esc(TOOLS[k].name)}"><div class="it">${toolIcon(k)}</div><span class="cnt">${c}</span></div>`; });
  h += '</div><div class="mc-sts">';
  for (let k = 0; k < S.storeN; k++) {
    const it = S.store[k];
    h += `<div class="c sc" data-i="${STB + k}">${it ? `<div class="it">${itIcon(it)}</div>${it.l >= 2 ? `<span class="lvb">${it.l}</span>` : ''}` : ''}</div>`;
  }
  if (S.storeN < STORE_MAX) h += `<button class="mc-stbuy" data-act="stbuy"><b>+</b><span><i>${UI.coin}</i>${STORE_COST(S.storeN)}</span></button>`;
  h += '</div>';
  box.innerHTML = h;
  box.querySelector('.mc-sts').scrollLeft = sx;
}
function makeBag(size, withGen) {
  const inn = [], ch = mainChains();
  for (let k = 0; k < size + 2; k++) inn.push(rollItem(size + 1, ch));
  if (withGen) inn.push(bagGen());
  if (Math.random() < .12 + size * .04) inn.splice(Math.floor(Math.random() * inn.length), 0, { tool: 'cut' });
  if (Math.random() < .03 + size * .02) inn.splice(Math.floor(Math.random() * inn.length), 0, { tool: 'up' });
  return bagGenRoll({ b: size, in: inn });
}
function placeItem(it) {
  if (S.onEv) { S.pendingItems.push(it); return false; }
  const i = firstEmpty();
  if (i < 0) { S.pendingItems.push(it); return false; }
  S.board[i] = it; fx.push({ t: 'pop', i }); return true;
}
function openBag(bi) {
  const bag = S.board[bi];
  const last = bag.in.length === 1;
  const t = last ? bi : nearestEmpty(bi);
  if (t < 0) { sfx('error'); toast('보드가 꽉 찼어요! 자리를 만들고 보따리를 열어 주세요.'); fx.push({ t: 'shake', i: bi }); renderBoard(); return; }
  const it = bag.in.shift();
  sfx('produce');
  S.board[t] = it;
  if (it.c) discover(it.c, it.l);
  else if (it.r) toast(`보따리에서 <b>${esc(RES[it.r].items[it.l - 1])}</b>${jo(RES[it.r].items[it.l - 1], '이', '가')} 나왔어요! 한 번 더 누르면 받아요.`, { icon: iconRes(it.r, it.l) });
  else if (it.tool) toast(`보따리에서 <b>${esc(TOOLS[it.tool].name)}</b>이 나왔어요! 재료에 끌어다 놓으면 써져요.`, { icon: toolIcon(it.tool) });
  else toast(`보따리에서 <b>${esc(CHAINS[it.g].gen)}</b>${jo(CHAINS[it.g].gen, '이', '가')} 나왔어요! 같은 생산기끼리 합쳐 보세요.`, { icon: iconGen(it.g) });
  if (last) { fx.push({ t: 'merge', i: t }); sel = t; }
  else fx.push({ t: 'spawn', from: bi, to: t }, { t: 'squish', i: bi });
  renderAll(); save();
}
function superProduce(gi) {
  const g = S.board[gi]; if (!g || !g.g) return;
  const gl = glOf(g), cost = superCost(gl);
  const t = nearestEmpty(gi);
  if (t < 0) { sfx('error'); toast('보드가 꽉 찼어요! 합치거나 팔아서 자리를 만들어 주세요.'); return; }
  tickEnergy();
  if (S.energy < cost) { sfx('error'); superOn = false; renderMode(); toast(`에너지가 ${cost}보다 적어서 ⚡×${cost} 생산을 껐어요.`); fx.push({ t: 'shake', i: gi }); renderBoard(); return; }
  spendEnergy(cost);
  const l = superLv(gl);
  sfx('produce');
  S.board[t] = { c: g.g, l };
  S.stats.made++;
  discover(g.g, l);
  fx.push({ t: 'spawn', from: gi, to: t }, { t: 'squish', i: gi });
  renderAll(); save();
}

// ---------- progression ----------
function gainXp(n) {
  S.xp += n;
  const ups = [];
  while (S.xp >= xpNeed(S.level)) {
    S.xp -= xpNeed(S.level);
    S.level++;
    const rew = { lv: S.level, e: 20, coins: S.level * 10, unlock: null };
    addEnergy(rew.e, true);
    S.coins += rew.coins; S.stars += 1;
    const c = UNLOCKS[S.level];
    if (c && !mainChains().includes(c)) { mainChains().push(c); rew.unlock = c; placeGenerator(c); }
    const size = Math.min(3, (S.level < 6 ? 1 : S.level < 12 ? 2 : 3) + (done('photo') ? 1 : 0));
    const bag = makeBag(size, S.level % 3 === 0);
    rew.bag = size; rew.gen = bag.in.some(x => x && x.g);
    placeItem(bag);
    placeItem({ x: 1 });
    ups.push(rew);
  }
  if (ups.length) setTimeout(() => showLevelUp(ups), 450);
}
function discover(c, l) {
  if (S.disc[c].includes(l)) return;
  S.disc[c].push(l);
  if (l === 1) return;
  sfx('discover');
  const bonus = l * 3;
  S.coins += bonus;
  toast(`<b>새 메뉴 발견!</b> ${esc(CHAINS[c].items[l - 1])} <span class="mc-mini">${UI.coin}+${bonus}</span>`, { icon: iconItem(c, l) });
  gainXp(l);
}
function placeGenerator(c) {
  if (S.onEv) { S.pendingGens.push(c); return; }
  const i = firstEmpty();
  if (i < 0) { S.pendingGens.push(c); return; }
  S.board[i] = { g: c };
  fx.push({ t: 'pop', i });
}
function placePending() {
  if (S.onEv) return;
  while (S.pendingGens.length) {
    const i = firstEmpty();
    if (i < 0) return;
    S.board[i] = { g: S.pendingGens.shift() };
    fx.push({ t: 'pop', i });
    toast(`<b>${esc(CHAINS[S.board[i].g].gen)}</b>${jo(CHAINS[S.board[i].g].gen, '을', '를')} 보드에 놓았어요!`, { icon: iconGen(S.board[i].g) });
  }
  while (S.pendingItems.length) {
    const i = firstEmpty();
    if (i < 0) return;
    S.board[i] = S.pendingItems.shift();
    fx.push({ t: 'pop', i });
  }
}
function firstEmpty() {
  for (let i = 0; i < S.rows * COLS; i++) if (!S.board[i]) return i;
  return -1;
}
function nearestEmpty(from) {
  const [r0, c0] = rc(from);
  let best = -1, bd = Infinity;
  for (let i = 0; i < S.rows * COLS; i++) {
    if (S.board[i]) continue;
    const [r, c] = rc(i);
    const d = (r - r0) ** 2 + (c - c0) ** 2 + Math.random() * 0.1;
    if (d < bd) { bd = d; best = i; }
  }
  return best;
}

// ---------- actions ----------
function produce(gi) {
  const c = S.board[gi].g;
  const t = nearestEmpty(gi);
  if (t < 0) { sfx('error'); toast('보드가 꽉 찼어요! 합치거나 팔아서 자리를 만들어 주세요.'); fx.push({ t: 'shake', i: gi }); renderBoard(); return; }
  // 아이스크림 가게 혜택은 '에너지를 안 쓰는' 것. 에너지가 0이면 혜택과 상관없이 생산 안 됨
  tickEnergy();
  if (S.energy < 1) { sfx('error'); fx.push({ t: 'shake', i: gi }); renderBoard(); openShop(true); return; }
  const free = done('ice') && Math.random() < 0.1;
  if (!free) spendEnergy(1);
  sfx('produce');
  const od = GEN_ODDS[glOf(S.board[gi])];
  const roll = () => { const r = Math.random(); return r < od[3] ? 5 : r < od[3] + od[2] ? 4 : r < od[3] + od[2] + od[1] ? 3 : r < od[3] + od[2] + od[1] + od[0] + 0.04 * D('window') ? 2 : 1; };
  const l = roll();
  S.board[t] = { c, l };
  S.stats.made++;
  discover(c, l);
  fx.push({ t: 'spawn', from: gi, to: t }, { t: 'squish', i: gi });
  if (Math.random() < od[4]) {
    const t2 = nearestEmpty(gi);
    if (t2 >= 0) { const l2 = roll(); S.board[t2] = { c, l: l2 }; discover(c, l2); fx.push({ t: 'spawn', from: gi, to: t2 }); toast('두 개가 한 번에 나왔어요!'); }
  }
  renderAll(); save();
}
function drop(from, to) {
  if (from === to || to < 0) return;
  if (to >= S.rows * COLS) { fx.push({ t: 'back', i: from }); renderBoard(); return; }
  const A = S.board[from], B = S.board[to];
  if (!B) { S.board[to] = A; S.board[from] = null; fx.push({ t: 'land', i: to }); sfx('drop'); }
  else if (A.g && B.g && A.g === B.g && glOf(A) === glOf(B) && glOf(A) < genMax()) {
    S.board[to] = { g: A.g, gl: glOf(A) + 1 }; S.board[from] = null; if ((S.gdisc[A.g] || 0) < glOf(A) + 1) S.gdisc[A.g] = glOf(A) + 1;
    S.stats.merges++;
    fx.push({ t: 'merge', i: to });
    sfx('levelup');
    toast(`<b>${esc(genName(A.g, glOf(A) + 1))}</b> Lv.${glOf(A) + 1}! 더 좋은 재료가 나와요.`, { icon: iconGen(A.g, glOf(A) + 1) });
  }
  else if (A.b && B.b && A.b === B.b && A.b < 3) {
    S.board[to] = bagGenRoll({ b: A.b + 1, in: [...B.in, ...A.in, rollItem(A.b + 2, mainChains())] }); S.board[from] = null;
    fx.push({ t: 'merge', i: to });
    sfx('merge', A.b + 2);
  }
  else if (chestMerge(A, B)) { S.board[to] = chestMerge(A, B); S.board[from] = null; fx.push({ t: 'merge', i: to }); sfx('merge', A.x + 2); }
  else if (resMerge(A, B)) {
    S.board[to] = resMerge(A, B); S.board[from] = null;
    S.stats.merges++; fx.push({ t: 'merge', i: to }); sfx('merge', A.l + 1);
  }
  else if (A.c && B.c && A.c === B.c && A.l === B.l && A.l < maxLvOf(A.c)) {
    S.board[to] = { c: A.c, l: A.l + 1 }; S.board[from] = null;
    S.stats.merges++;
    fx.push({ t: 'merge', i: to });
    sfx('merge', A.l + 1);
    discover(A.c, A.l + 1);
  } else { S.board[to] = A; S.board[from] = B; fx.push({ t: 'swap', i: from }, { t: 'land', i: to }); sfx('drop'); }
  sel = to;
  placePending();
  renderAll(); save();
}
async function sellSelected() {
  const it = S.board[sel];
  if (it && it.tool) {
    const k = it.tool, tp = toolSell(k);
    if (!(await confirmBox(`<b>${esc(TOOLS[k].name)}</b> 1개를 판매할까요?`, `판매 +${tp}`))) return;
    if (S.board[sel] !== it) return;
    if (tN(it) > 1) it.n--; else { S.board[sel] = null; sel = -1; }
    S.coins += tp; sfx('coin');
    toast(`${esc(TOOLS[k].name)} 판매 <span class="mc-mini">${UI.coin}+${tp}</span>`, { icon: toolIcon(k) });
    placePending();
    renderAll(); save();
    return;
  }
  if (!it || !it.c) return;
  const price = sellPrice(it.l);
  if (it.l >= 5 && !(await confirmBox(`<b>${esc(CHAINS[it.c].items[it.l - 1])}</b>을(를) 판매할까요?<br><span class="mc-sub">주문에 쓰면 훨씬 많이 받을 수 있어요.</span>`, `판매 +${price}`))) return;
  const i = sel;
  S.board[i] = null; S.coins += price;
  sfx('coin');
  lastSold = { i, it, price, t: Date.now() };
  sel = -1;
  toast(`${esc(CHAINS[it.c].items[it.l - 1])} 판매 <span class="mc-mini">${UI.coin}+${price}</span>`, {
    icon: iconItem(it.c, it.l), ms: 4000,
    action: { label: '되돌리기', fn: () => {
      if (!lastSold || lastSold.i !== i || S.board[i] || S.coins < price) return;
      S.board[i] = it; S.coins -= price; sel = i; lastSold = null; fx.push({ t: 'pop', i }); renderAll(); save();
    } },
  });
  placePending();
  renderAll(); save();
}
async function unlockRow() {
  const cost = ROW_COST[S.rows];
  if (!cost) return;
  if (S.coins < cost) { toast(`코인이 부족해요 (${cost} 필요)`); return; }
  if (!(await confirmBox(`보드 한 줄을 넓힐까요?`, `${cost} 코인으로 열기`))) return;
  S.coins -= cost; S.rows++;
  sfx('decor');
  for (let c = 0; c < COLS; c++) fx.push({ t: 'pop', i: (S.rows - 1) * COLS + c });
  placePending();
  renderAll(); save();
}

// ---------- DOM ----------
const $ = q => document.querySelector(q);
const ICO = {
  mail: '<svg viewBox="0 0 64 64"><rect x="8" y="16" width="48" height="34" rx="7" fill="#fff6e8" stroke="#5b3a32" stroke-width="4"/><path d="M10 20l22 17 22-17" fill="none" stroke="#5b3a32" stroke-width="4" stroke-linejoin="round"/><path d="M32 44c-6-4-9-7-9-10a4 4 0 0 1 9-2 4 4 0 0 1 9 2c0 3-3 6-9 10z" fill="#ff8fa3" stroke="#5b3a32" stroke-width="2.5" stroke-linejoin="round"/></svg>',
  book: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 6c-2-1.5-5-2-8-1.5v14c3-.5 6 0 8 1.5 2-1.5 5-2 8-1.5v-14c-3-.5-6 0-8 1.5z"/><path d="M12 6v14"/></svg>',
  gear: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="3"/><path d="M12 2.5v2.2M12 19.3v2.2M4.6 4.6l1.6 1.6M17.8 17.8l1.6 1.6M2.5 12h2.2M19.3 12h2.2M4.6 19.4l1.6-1.6M17.8 6.2l1.6-1.6"/></svg>',
  close: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M6 6l12 12M18 6L6 18"/></svg>',
  check: '<svg viewBox="0 0 24 24" fill="none" stroke="#fff" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"><path d="M5 12.5l4.5 4.5L19 7"/></svg>',
  shop: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 10v10h16V10"/><path d="M3 10l2-6h14l2 6c0 1.5-1.3 2.5-3 2.5S15 11.5 15 10c0 1.5-1.3 2.5-3 2.5S9 11.5 9 10c0 1.5-1.3 2.5-3 2.5S3 11.5 3 10z"/><path d="M10 20v-5h4v5"/></svg>',
  box: '<svg viewBox="0 0 24 24" stroke="#5b3a32" stroke-width="2" stroke-linejoin="round"><path d="M3 9h18v11a1.5 1.5 0 0 1-1.5 1.5h-15A1.5 1.5 0 0 1 3 20z" fill="#f3c58f"/><path d="M2 5.5A1.5 1.5 0 0 1 3.5 4h17A1.5 1.5 0 0 1 22 5.5V9H2z" fill="#ffb3c1"/><rect x="9" y="12" width="6" height="3" rx="1.5" fill="#fff7ec"/></svg>',
  plus: '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3.2" stroke-linecap="round"><path d="M12 6v12M6 12h12"/></svg>',
};

