    box.innerHTML = `<div class="ii evo" data-act="evo" title="머지 단계 보기">${iconGen(it.g, gl)}<span class="q">?</span></div><div class="tx"><b>${esc(genName(it.g, gl))} <span class="mc-glv">Lv.${gl}</span></b><div class="mc-sub">${esc((GEN_DESC[it.g] || [])[gl - 1] || `${ch.name} 재료를 만들어 주는 생산기예요.`)}</div></div>`;
