// ---------- effects ----------
function burst(r) {
  const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
  const cols = ['#ff8fa3', '#ffd75a', '#8fd6b9', '#fff', '#ffb3c1'];
  for (let k = 0; k < 9; k++) {
    const d = document.createElement('div');
    d.className = 'mc-pt';
    const s = 5 + Math.random() * 6;
    d.style.cssText = `width:${s}px;height:${s}px;border-radius:${k % 3 ? '50%' : '2px'};background:${pick(cols)};border:1.5px solid #5b3a32`;
    document.body.appendChild(d);
    const ang = Math.PI * 2 * k / 9 + Math.random() * .4, dist = r.width * (.55 + Math.random() * .4);
    d.animate([{ transform: `translate(${cx}px,${cy}px) scale(1)`, opacity: 1 }, { transform: `translate(${cx + Math.cos(ang) * dist}px,${cy + Math.sin(ang) * dist}px) scale(.3) rotate(120deg)`, opacity: 0 }], { duration: 480 + Math.random() * 200, easing: 'cubic-bezier(.2,.8,.4,1)' }).onfinish = () => d.remove();
  }
}
function flyCoins(from, n, target = '#mc-co', icon = UI.coin) {
  const tEl = $(target);
  if (!tEl) return;
  const to = tEl.getBoundingClientRect();
  for (let k = 0; k < n; k++) {
    const d = document.createElement('div');
    d.className = 'mc-pt';
    d.style.cssText = 'width:22px;height:22px';
    d.innerHTML = icon;
    document.body.appendChild(d);
    const sx = from.left + from.width / 2 - 11 + (Math.random() - .5) * 30, sy = from.top + from.height / 2 - 11;
    const ex = to.left + 4, ey = to.top + 3;
    const an = d.animate([
      { transform: `translate(${sx}px,${sy}px) scale(.5)`, opacity: 0 },
      { transform: `translate(${sx}px,${sy - 18}px) scale(1.1)`, opacity: 1, offset: .25 },
      { transform: `translate(${ex}px,${ey}px) scale(.8)`, opacity: 1 }], { duration: 650, delay: k * 70, easing: 'cubic-bezier(.5,0,.6,1)', fill: 'backwards' });
    an.onfinish = () => { d.remove(); jelly(tEl, .3, 300); };
  }
}

// ---------- drag ----------
let drag = null;
function onDown(ev) {
  if (drag || ev.button > 0) return;
  const cell = ev.target.closest('.c');
  if (!cell) return;
  const i = +cell.dataset.i;
  if (!cellOk(i)) return;
  if (!getIt(i)) {
    if (i >= TLB) { const k = TK[i - TLB]; sfx('ui'); toast(`${TOOLS[k].name}이 없어요. 상점에서 하루 1개 살 수 있어요.`, { icon: toolIcon(k) }); return; }
    if (sel !== -1) { sel = -1; renderBoard(); renderInfo(); } return;
  }
  const it = cell.querySelector('.it');
  const press = it && it.animate([{ transform: 'scale(1,1)' }, { transform: 'scale(1.04,.95)' }], { duration: 100, fill: 'forwards', easing: 'ease-out' });
  drag = { i, pointerId: ev.pointerId, x0: ev.clientX, y0: ev.clientY, moved: false, ghost: null, tgt: -1, cell, press, px: ev.clientX, py: ev.clientY, lx: ev.clientX, tilt: 0, tTilt: 0, raf: 0 };
  try { ev.currentTarget.setPointerCapture(ev.pointerId); } catch (_) { }
  applyPull();
}
function ghostLoop() {
  if (!drag || !drag.ghost) return;
  const cs = parseFloat(getComputedStyle($('#mc')).getPropertyValue('--cell')) || 40;
  drag.tilt += (drag.tTilt - drag.tilt) * .15;
  drag.tTilt *= .85;
  drag.ghost.style.transform = `translate(${drag.px - cs / 2}px,${drag.py - cs * .55}px) rotate(${drag.tilt.toFixed(2)}deg)`;
  drag.raf = requestAnimationFrame(ghostLoop);
}
function onMove(ev) {
  if (!drag || drag.pointerId !== ev.pointerId) return;
  const dx = ev.clientX - drag.x0, dy = ev.clientY - drag.y0;
  if (!drag.moved) {
    if (dx * dx + dy * dy < 64) return;
    drag.moved = true;
    drag.press?.cancel();
    const g = document.createElement('div');
    g.className = 'mc-ghost';
    const csz = drag.cell.getBoundingClientRect().width;
    g.style.width = csz + 'px'; g.style.height = csz + 'px';
    g.innerHTML = `<div class="gi">${drag.cell.querySelector('.it').innerHTML}</div>`;
    document.body.appendChild(g);
    drag.ghost = g;
    drag.cell.classList.add('lift');
    haptic(5); sfx('pick');
    drag.raf = requestAnimationFrame(ghostLoop);
  }
  const vx = ev.clientX - drag.lx;
  drag.lx = ev.clientX;
  drag.tTilt = Math.max(-7, Math.min(7, drag.tTilt * .5 + vx * .6));
  drag.px = ev.clientX; drag.py = ev.clientY;
  const ue = document.elementFromPoint(ev.clientX, ev.clientY);
  const bx = ue?.closest('.mc-boxb');
  document.querySelector('.mc-boxb')?.classList.toggle('tgt', !!bx && !!getIt(drag.i));
  const under = ue?.closest('.mc-board .c');
  const t = bx ? -2 : under ? +under.dataset.i : -1;
  if (t !== drag.tgt) {
    document.querySelectorAll('.c.tgt').forEach(x => x.classList.remove('tgt', 'mrg'));
    drag.tgt = t;
    if (t >= 0 && t !== drag.i && cellOk(t) && t < TLB) {
      under.classList.add('tgt');
      const A = getIt(drag.i), B = getIt(t);
      if (A && B && ((A.tool && B.tool === A.tool) || (A.tool && B.c && (A.tool === 'cut' ? B.l >= 2 : B.l < maxLvOf(B.c)) && t < STB) || (A.c && A.c === B.c && A.l === B.l && A.l < maxLvOf(A.c)) || (A.g && A.g === B.g && glOf(A) === glOf(B) && glOf(A) < genMax()) || (A.b && A.b === B.b && A.b < 3) || resMerge(A, B) || chestMerge(A, B))) {
        under.classList.add('mrg');
        jelly(under.querySelector('.it'), .3, 320);
        haptic(4);
      }
    }
  }
}
function onUp(ev) {
  if (!drag || drag.pointerId !== ev.pointerId) return;
  const d = drag;
  cleanupDrag();
  if (d.moved) {
    if (d.tgt === -2) toBox(d.i);
    else if (d.tgt >= 0 && d.tgt !== d.i && cellOk(d.tgt)) dropAny(d.i, d.tgt);
    else { sfx('drop'); if (d.i < STB) { fx.push({ t: 'back', i: d.i }); sel = d.i; } renderBoard(); renderStore(); renderInfo(); }
  } else {
    if (d.i >= STB) {
      sfx('tap'); jelly(d.cell.querySelector('.it'), .3, 300);
      if (d.i >= TLB) { const k = TK[d.i - TLB]; toast(`<b>${esc(TOOLS[k].name)}</b> ${S.tools[k]}개 · 판 위 재료에 끌어다 놓아 써요.`, { icon: toolIcon(k) }); }
      return;
    }
    const it = S.board[d.i];
    const was = sel === d.i;
    sel = d.i;
    if (it.r && was) useRes(d.i);
    else if (it.x) openChest(d.i);
    else if (it.g) { if (superOn) superProduce(d.i); else produce(d.i); }
    else if (it.b) openBag(d.i);
    else { sfx('tap'); fx.push({ t: 'land', i: d.i }); renderBoard(); renderInfo(); }
  }
}
function cancelDrag() { if (drag) { cleanupDrag(); renderBoard(); } }
function cleanupDrag() {
  if (drag) { cancelAnimationFrame(drag.raf); drag.press?.cancel(); }
  drag?.ghost?.remove();
  document.querySelectorAll('.c.tgt,.c.lift').forEach(x => x.classList.remove('tgt', 'mrg', 'lift'));
  document.querySelector('.mc-boxb.tgt')?.classList.remove('tgt');
  drag = null;
}

// ---------- toasts & modals ----------
function toast(html, opt = {}) {
  const box = $('.mc-toasts');
  if (!box) return;
  for (const old of box.children) if (old.dataset.k === html) old.remove();
  const t = document.createElement('div');
  t.dataset.k = html;
  t.className = 'mc-toast';
  t.innerHTML = (opt.icon ? `<div class="ti">${opt.icon}</div>` : '') + `<div>${html}</div>`;
  if (opt.action) {
    const b = document.createElement('button');
    b.className = 'mc-btn pk';
    b.textContent = opt.action.label;
    b.onclick = () => { opt.action.fn(); t.remove(); };
    t.appendChild(b);
  }
  box.appendChild(t);
  while (box.children.length > 3) box.firstChild.remove();
  setTimeout(() => { t.animate([{ opacity: 1 }, { opacity: 0, transform: 'translateY(-8px)' }], { duration: 250 }).onfinish = () => t.remove(); }, opt.ms || 2600);
}
