// ---------- neighborhood decoration ----------
let curArea = 0;
const eul = w => { const c = w.charCodeAt(w.length - 1) - 0xac00; return c >= 0 && c < 11172 && c % 28 ? '을' : '를'; };
function defaultArea() {
  let k = 0;
  AREAS.forEach((a, i) => { if (areaOpen(i)) k = i; });
  const firstOpenUnfinished = AREAS.findIndex((a, i) => areaOpen(i) && !areaFull(a));
  return firstOpenUnfinished >= 0 ? firstOpenUnfinished : k;
}
let cfPop = null;
function showCfPop(k) {
  const v = $('.mc-cafe'), box = v && v.querySelector('.cf-sel'); if (!box) return;
  const A = AREAS[curArea];
  if (!areaOpen(curArea)) { box.innerHTML = ''; return; }
  const cu = curOf(A), gate0 = A.event && D('xbase') < 1;
  let d = k && A.spots.find(x => x.k === k);
  if (!d || D(d.k) >= 2) {
    d = A.spots.filter(x => D(x.k) < 2 && !(gate0 && x.k !== 'xbase')).sort((p, q) => p.costs[D(p.k)] - q.costs[D(q.k)])[0];
  }
  if (!d) { box.innerHTML = `<div class="cf-done"><b>${esc(A.name)} 완성!</b><span class="mc-sub">${A.perk ? `완성 보너스 · ${esc(A.perk)} 적용 중` : '마을에서 구경해 보세요'}</span></div>`; cfPop = null; return; }
  cfPop = d.k;
  v.querySelectorAll('.cf-mk').forEach(e => e.classList.toggle('sel', e.dataset.k === d.k));
  const lv = D(d.k), cost = d.costs[lv], gate = gate0 && d.k !== 'xbase', ok = S[cu] >= cost && !gate;
  const next = Object.assign({}, S.decor, { [d.k]: lv + 1 });
  box.innerHTML = `<div class="cf-card"><div class="th">${areaScene(A.k, next, paintBox(A.k, d.k) || SPOT_BOX[d.k])}</div>
    <div class="tx"><b>${esc(d.look[lv + 1])} ${esc(d.name)}</b><span class="cf-pips"><i class="${lv >= 1 ? 'on' : ''}"></i><i></i></span>
    <div class="mc-sub">${esc(d.perk ? '보너스 · ' + d.perk(lv + 1) : d.desc[lv])}</div></div>
    <button class="mc-btn ${ok ? 'pk' : 'wh'}" data-cf="up" data-k="${d.k}" ${ok ? '' : 'disabled'}>${lv === 0 ? '꾸미기' : '업그레이드'}<span class="c"><i>${cu === 'snow' ? SNOW : UI.star}</i>${cost}</span></button></div>`;
}
function openCafe(ai) {
  if ($('.mc-cafe')) return;
  curArea = ai == null ? defaultArea() : ai;
  cfPop = null;
  const v = document.createElement('div');
  v.className = 'mc-cafe lst';
  v.innerHTML = `<div class="cf-top"><button class="mc-btn wh" data-cf="back">${$('.mc-town') ? '← 마을' : '← 주방'}</button><div class="cf-ti">동네 꾸미기</div><div class="mc-pill cf-st"><span class="ic">${UI.star}</span><span class="v"></span>&nbsp;</div></div>
    <div class="cf-strip"></div>
    <div class="cf-scene"></div>
    <div class="cf-prog"><span class="pt"></span><div class="bar"><i></i></div></div>
    <div class="cf-sel"></div>
    <div class="cf-list"></div>
    <div class="cf-foot"><button class="mc-btn wh" data-cf="dex">${ICO.book.replace('<svg', '<svg style="width:18px;height:18px"')} 메뉴 도감</button></div>`;
  $('.mc-panel').appendChild(v);
  v.addEventListener('click', ev => {
    const b = ev.target.closest('[data-cf]');
    if (b) {
      const a = b.dataset.cf;
      if (a !== 'up') sfx('ui');
      if (a === 'back') closeCafe();
      else if (a === 'dex') openDex();
      else if (a === 'up') { if (D(b.dataset.k) >= 1) cfPop = null; upgradeDecor(b.dataset.k); }
      else if (a === 'mk') { jelly(b, .4, 300); showCfPop(b.dataset.k); const c = v.querySelector('.cf-card'); c && jelly(c, .25, 300); }
      else if (a === 'list') { v.classList.toggle('lst'); stPop = null; renderTown(true); }
      else if (a === 'area') { curArea = +b.dataset.i; cfPop = null; v.querySelector('.cf-list').scrollTop = 0; renderCafe(); }
      return;
    }
    const spt = ev.target.closest('.cf-scene [data-spot]');
    if (spt && v.classList.contains('lst')) {
      const row = v.querySelector(`.cf-row[data-k="${spt.dataset.spot}"]`);
      if (row) { row.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); row.classList.remove('flash'); void row.offsetWidth; row.classList.add('flash'); }
    }
  });
  renderCafe();
  setTimeout(() => v.querySelector('.cf-tab.on')?.scrollIntoView({ inline: 'center', block: 'nearest' }), 30);
}
function closeCafe() {
  const v = $('.mc-cafe');
  if (!v) return;
  v.animate([{ opacity: 1 }, { opacity: 0, transform: 'translateY(30px)' }], { duration: 180 }).onfinish = () => v.remove();
  if ($('.mc-town')) renderTown();
}

// ---------- 마을·가게 그림 (리스 플러그인: GitHub 묶음 파일에서 받아 옴) ----------
const EXT_BASES = globalThis.__MC_EXT_BASE ? [globalThis.__MC_EXT_BASE] : [
  'https://raw.githubusercontent.com/shakeit08/risu-plugins/main/sweet_merge_cafe_img/',
  'https://cdn.jsdelivr.net/gh/shakeit08/risu-plugins@main/sweet_merge_cafe_img/',
];
// 리스 플러그인: 그림은 깃허브 주소로 바로 띄우고, 안 열리면 jsDelivr 주소로 한 번 더
const IMG_RAW = 'https://raw.githubusercontent.com/shakeit08/risu-plugins/main/';
const imgAlt = v => v.startsWith(IMG_RAW) ? 'https://cdn.jsdelivr.net/gh/shakeit08/risu-plugins@main/' + v.slice(IMG_RAW.length) : null;
if (!APP) document.addEventListener('error', ev => {
  const t = ev.target, a = t && t.getAttribute ? (t.tagName === 'IMG' ? 'src' : t.localName === 'image' ? 'href' : null) : null;
  if (!a) return;
  const u = imgAlt(t.getAttribute(a) || ''); if (u) t.setAttribute(a, u);
}, true);
const extAll = Object.values(EXT_FILES || {}), isStoryExt = n => n.startsWith('story-');
// 이야기 일러스트는 마을 그림과 따로, 필요할 때 받음
const extNames = extAll.filter(n => !isStoryExt(n)), storyNames = extAll.filter(isStoryExt);
let extReady = !extNames.length, extJob = null, extDone = 0, storyJob = null;
// 웹리스에서 응답이 섞이지 않게 묶음 파일은 항상 하나씩 차례로 받음
let extLock = Promise.resolve();
const extSeq = fn => { const p = extLock.then(fn); extLock = p.catch(() => { }); return p; };
const extHave = {};
async function extGet(url, from) {
  const h = { Range: 'bytes=' + (from || 0) + '-' };
  const nf = Risuai.nativeFetch ? (u => Risuai.nativeFetch(u, { method: 'GET', headers: h })) : (u => fetch(u, { headers: h }));
  const r = await Promise.race([nf(url), new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 45000))]);
  if (!r || !(r.status === 200 || r.status === 206)) throw new Error('HTTP ' + (r && r.status));
  let b;
  if (r.body && typeof r.body.getReader === 'function') {
    // 조각 단위로 읽어서, 중간에 끊겨도 받은 데까지는 남김
    const rd = r.body.getReader(), cs = []; let n = 0;
    try { for (;;) { const { done, value } = await rd.read(); if (done) break; const v = ArrayBuffer.isView(value) ? new Uint8Array(value.buffer, value.byteOffset, value.byteLength) : new Uint8Array(value); cs.push(v); n += v.length; } }
    catch (e) { if (!n) throw e; }
    b = new Uint8Array(n); let o = 0; for (const v of cs) { b.set(v, o); o += v.length; }
  } else {
    const buf = typeof r.arrayBuffer === 'function' ? await r.arrayBuffer() : r.data;
    b = ArrayBuffer.isView(buf) ? new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength) : new Uint8Array(buf);
  }
  // 이어받기를 요청했는데 처음부터 다시 온 경우
  return from && r.status === 200 ? b.subarray(from) : b;
}
// 중간에 끊겨 오면 끊긴 곳부터 이어받음
async function extFull(url) {
  let b = new Uint8Array(0), err;
  for (let k = 0; k < 8; k++) {
    if (b.length >= 8) {
      const hl = b[4] | b[5] << 8 | b[6] << 16 | b[7] << 24;
      if (b.length >= 8 + hl) {
        let need = 8 + hl;
        for (const x of JSON.parse(new TextDecoder().decode(b.subarray(8, 8 + hl)))) need = Math.max(need, 8 + hl + x[2] + x[3]);
        if (b.length >= need) return b.subarray(0, need);
      }
    }
    try {
      const more = await extGet(url, b.length);
      if (!more.length) throw new Error('short file');
      const c = new Uint8Array(b.length + more.length); c.set(b); c.set(more, b.length); b = c;
    } catch (e) { err = e; if (/^HTTP 4/.test(e?.message)) throw e; }
  }
  throw err || new Error('short file');
}
// 받은 묶음 파일 확인하고 그림 주소로 풀기
async function extParse(name, b) {
  if (String.fromCharCode(b[0], b[1], b[2], b[3]) !== 'MCB1') throw new Error('bad file');
  // 다른 파일 내용이 섞여 오는 경우가 있어서, 파일 이름의 지문(sha1 앞 10자리)과 맞는지 확인
  const want = (name.match(/\.([0-9a-f]{10})\.bin$/) || [])[1];
  if (want && globalThis.crypto && crypto.subtle) {
    const h = [...new Uint8Array(await crypto.subtle.digest('SHA-1', b))].map(x => x.toString(16).padStart(2, '0')).join('').slice(0, 10);
    if (h !== want) throw new Error('mixed file');
  }
  const hl = b[4] | b[5] << 8 | b[6] << 16 | b[7] << 24, idx = JSON.parse(new TextDecoder().decode(b.subarray(8, 8 + hl))), o = 8 + hl, m = {};
  for (const [t, mime, off, len] of idx) {
    const p = o + off;
    if (p + len > b.length) throw new Error('short file');
    if (mime === 'image/webp' && !(b[p] === 82 && b[p + 1] === 73 && b[p + 8] === 87 && b[p + 9] === 69)) throw new Error('broken image');
  }
  for (const [t, mime, off, len] of idx) m[t] = URL.createObjectURL(new Blob([b.slice(o + off, o + off + len)], { type: mime }));
  return m;
}
// 웹리스는 모든 요청이 같은 주소(GET /proxy2)로 나가서 브라우저가 첫 파일 응답을 계속 돌려줌.
// 성공(2xx)하는 POST를 한 번 보내면 그 주소의 캐시가 지워짐 (RFC 9111 4.4)
async function extBust(name) {
  if (!Risuai.nativeFetch) return;
  for (const [u, ct, body] of [['https://purge.jsdelivr.net/', 'application/json', JSON.stringify({ path: ['/gh/shakeit08/risu-plugins@main/sweet_merge_cafe_img/' + name] })], ['https://api.github.com/markdown/raw', 'text/plain', 'x']]) {
    try {
      const r = await Promise.race([Risuai.nativeFetch(u, { method: 'POST', headers: { 'Content-Type': ct }, body }), new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 15000))]);
      if (r && r.status >= 200 && r.status < 300) return;
    } catch (_) { }
  }
}
// 제대로 받은 묶음 파일은 기기에 보관해 두고 다음부터는 바로 씀
const EXT_DB = 'mc_sweet_merge_cafe_img';
let extDbP = null;
function extDb() {
  if (!extDbP) extDbP = new Promise(res => {
    try {
      const q = indexedDB.open(EXT_DB, 1);
      q.onupgradeneeded = () => q.result.createObjectStore('bin');
      q.onsuccess = () => res(q.result); q.onerror = () => res(null); q.onblocked = () => res(null);
    } catch (_) { res(null); }
  });
  return extDbP;
}
async function extDbDo(mode, fn) {
  const db = await extDb(); if (!db) return null;
  return new Promise(res => {
    try { const tx = db.transaction('bin', mode), st = tx.objectStore('bin'), q = fn(st); tx.oncomplete = () => res(q ? q.result : true); tx.onerror = tx.onabort = () => res(null); }
    catch (_) { res(null); }
  });
}
const extDbGet = name => extDbDo('readonly', st => st.get(name));
const extDbPut = (name, b) => extDbDo('readwrite', st => st.put(b.slice().buffer, name));
// 이름(지문)이 바뀐 옛 파일은 지움
const extDbClean = () => extDbDo('readwrite', st => { const q = st.getAllKeys(); q.onsuccess = () => q.result.forEach(k => { if (!extAll.includes(k)) st.delete(k); }); return null; });
async function extOne(name) {
  try {
    const c = await extDbGet(name);
    if (c) { const mm = await extParse(name, new Uint8Array(c)); if (!isStoryExt(name)) { extDone++; $('.mc-extp')?.replaceChildren(`${extDone}/${extNames.length}`); } return mm; }
  } catch (_) { }
  let err;
  for (const q of ['', '?r=' + Date.now()]) for (const base of EXT_BASES) for (let t = 0; t < 2; t++) {
    try {
      const b = await extFull(base + name + q);
      // 받다가 끊기거나 깨진 파일이면 다른 주소로 다시 받음
      const mm = await extParse(name, b);
      extDbPut(name, b);
      if (!isStoryExt(name)) { extDone++; $('.mc-extp')?.replaceChildren(`${extDone}/${extNames.length}`); }
      return mm;
    } catch (e) {
      err = e;
      // 섞여 온 경우: 캐시를 지우고 같은 주소로 한 번 더
      if (e?.message === 'mixed file' && !t) { await extBust(name); continue; }
      break;
    }
  }
  throw err;
}
function loadExt() {
  if (extReady) return Promise.resolve(true);
  if (!extJob) {
    // 한꺼번에 받으면 웹리스에서 응답이 섞이는 일이 있어서 하나씩 차례로 받음
    extJob = (async () => {
      extDone = extNames.filter(n => extHave[n]).length;
      extDbClean();
      for (const n of extNames) {
        if (extHave[n]) continue;
        try { const mm = await extSeq(() => extOne(n)); extFill(mm); extHave[n] = true; }
        catch (e) { console.log(TAG, 'ext load fail', n, e?.message || e); }
      }
      extReady = extNames.every(n => extHave[n]);
      extJob = null;
      return extNames.some(n => extHave[n]);
    })();
  }
  return extJob;
}
// 이야기 일러스트 받기 (리스 플러그인)
function loadStory() {
  if (!storyNames.length || storyNames.every(n => extHave[n])) return Promise.resolve(true);
  if (!storyJob) storyJob = (async () => {
    for (const n of storyNames) {
      if (extHave[n]) continue;
      try { const mm = await extSeq(() => extOne(n)); extFill(mm); extHave[n] = true; }
      catch (e) { console.log(TAG, 'story load fail', n, e?.message || e); }
    }
    storyJob = null;
    return storyNames.every(n => extHave[n]);
  })();
  return storyJob;
}
