      `<g transform="rotate(${k * 45})">${ic}${p[0] === 'x' ? '' : `<text y="${-R * .44}" text-anchor="middle" font-size="${p[1] >= 100 ? 15 : 17}" fill="#5b3a32" font-family="MCJua,Jua,sans-serif">${p[1]}</text>`}</g>`;
