    if (A.ch2 && !ad[A.ch2]) return;
    if (!LETTERS[A.key]) return;
    const ar = A.ch2 ? AREAS.find(x => x.k === A.ch2) : null, vi = villageOf(ar ? (ar.ch || 1) : 1);
