function playStory(key, cb) {
  const lines = STORY[key];
  const fin = () => { try { cb && cb(); } catch (_) { } };
  if (!lines || !S.settings.story) { S.story.seen[key] = true; fin(); return; }
  S.story.seen[key] = true; save();
  playLines(lines, cb, true, key);
}
function playLines(lines, cb, force, key) {
  const fin = () => { try { cb && cb(); } catch (_) { } };
  if (!force && !S.settings.story) { fin(); return; }
  $('.mc-story')?.remove();
  const el = document.createElement('div');
  el.className = 'mc-story';
  const cg = key && STORY_CG[key] && (APP || STORY_IMG) ? STORY_CG[key] : null;
  el.innerHTML = `<button class="mc-btn wh st-skip">건너뛰기</button>${cg ? `<div class="st-cg"><img alt="" draggable="false"></div>` : ''}<div class="st-chat"></div><div class="st-next"></div>`;
  if (cg) {
    const im = el.querySelector('.st-cg img'); im.onerror = () => im.parentNode.remove(); im.onload = () => im.parentNode.classList.add('in');
    const u = cgSrc(cg);
    if (u) im.src = u;
    // 플러그인: 아직 안 받은 일러스트는 받는 대로 띄움
    else loadStory().then(() => { const v = cgSrc(cg); if (!el.isConnected) return; if (v) im.src = v; else im.parentNode.remove(); });
  }
  $('.mc-panel').appendChild(el);
  const chat = el.querySelector('.st-chat');
  const side = {};
  let i = 0, lastSide = 'r';
  const end = () => { el.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 160 }).onfinish = () => { el.remove(); fin(); }; };
  const show = () => {
    const [a, t, happy] = lines[i];
    if (!side[a]) side[a] = lastSide === 'l' && Object.keys(side).length ? 'r' : Object.keys(side).length ? (lastSide === 'l' ? 'r' : 'l') : 'l';
    const sd = side[a]; lastSide = sd;
    chat.querySelectorAll('.st-row').forEach(r => r.classList.add('old'));
    const rows = chat.querySelectorAll('.st-row'); if (rows.length >= 2) rows[0].remove();
    const row = document.createElement('div');
    row.className = 'st-row ' + sd;
    row.innerHTML = `<div class="st-face">${iconAnimal(a, happy !== 0)}<span class="st-name">${esc(ANIMALS[a].name)}</span></div><div class="st-bub">${esc(t)}</div>`;
    chat.appendChild(row);
    row.animate([{ opacity: 0, transform: `translateX(${sd === 'l' ? -14 : 14}px)` }, { opacity: 1, transform: 'none' }], { duration: 240, easing: 'cubic-bezier(.3,1.3,.5,1)' });
    jelly(row.querySelector('.st-face'), .5, 360);
    el.querySelector('.st-next').textContent = i === lines.length - 1 ? '닫기' : '탭해서 계속 ▼';
  };
  el.addEventListener('click', ev => {
    if (ev.target.closest('.st-skip')) { sfx('ui'); end(); return; }
    sfx('tap'); i++;
    if (i >= lines.length) end(); else show();
  });
  show();
}

// ---------- open / close ----------
async function openGame() {
  try {
    if (!S) S = await loadState();
    if (!uiBuilt) buildUI();
    tickEnergy();
    await Risuai.showContainer('fullscreen');
    visible = true;
    if (!extReady) loadExt();
    requestAnimationFrame(() => {
      renderAll(); layout(); watchLayout();
      if (S.chatBonus > 0) { toast(`채팅하는 동안 에너지가 찼어요 <span class="mc-mini">${UI.bolt}+${S.chatBonus}</span>`); S.chatBonus = 0; save(); }
      { const nm = checkMail(); if (nm) toast(`우편함에 새 편지가 ${nm}통 왔어요! 마을에서 열어 보세요.`, { icon: MAIL_ICON() }); fetchDevMail(); }
      setTimeout(() => runTut('k'), 900);
      const evr = checkEvent();
      if (S.evTab && S.ev && !S.onEv) swapEv();
      if (evr) renderAll();
      const prevVer = S.seenVer;
      if (prevVer !== VER) { if (prevVer ? verCmp(prevVer, '2.13.2') < 0 : S.level > 1) { addEnergy(100, true); renderTop(); toast(`업데이트 기념 선물이에요! <span class="mc-mini">${UI.bolt}+100</span>`); }
        // 2.21.27 업데이트 선물: 왕관 선물 상자 3개
        if (prevVer ? verCmp(prevVer, '2.21.27') < 0 : S.level > 1) { for (let k = 0; k < 3; k++) placeItem({ x: 3 }); renderBoard(); toast(`업데이트 선물로 <b>${esc(CHEST[3].name)}</b> 3개가 도착했어요!`, { icon: iconChest(3) }); } S.seenVer = VER; if (prevVer || S.level > 1) setTimeout(() => { if (!$('.mc-story') && !$('.mc-modal')) openNotes(prevVer ? (verCmp(prevVer, '2.13.2') > 0 && verCmp(prevVer, '2.15.0') <= 0 ? '2.13.2' : prevVer) : NOTES[4][0]); }, 500); }
      if (!S.story.intro) { S.story.intro = true; save(); playStory('intro'); }
      else if (evr === 'start' && !S.story.seen.xmas_intro) setTimeout(() => playStory('xmas_intro'), 400);
      else if (evr && evr.end) { playStory('xmas_end'); if (evr.gain) toast(`크리스마스 판에 남은 물건을 정산했어요 <span class="mc-mini">${UI.coin}+${evr.gain}</span>`); }
      save();
      if (S.pendingGens.length || S.pendingItems.length) { placePending(); renderAll(); save(); }
    });
  } catch (err) { console.log(TAG, 'open fail', err?.message || err); }
}
async function closeGame() {
  visible = false;
  cleanupDrag();
  $('.mc-modal')?.remove();
  $('.mc-cafe')?.remove();
  try { await Risuai.hideContainer(); } finally { await flush(); }
}

// ---------- boot ----------
const MENU_ICON = '<svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M6 13h12l-1.6 7.2a1 1 0 0 1-1 .8H8.6a1 1 0 0 1-1-.8z"/><path d="M5.5 13a3 3 0 0 1 1.3-5.2A4.5 4.5 0 0 1 12 4.5a4.5 4.5 0 0 1 5.2 3.3A3 3 0 0 1 18.5 13"/><path d="M10 13l.5 8M14 13l-.5 8"/></svg>';
try {
  S = await loadState();
  tickEnergy();
  await Risuai.registerButton({ name: '달콤 머지 카페', icon: MENU_ICON, iconType: 'html', location: 'chat' }, openGame);
  await Risuai.registerSetting('달콤 머지 카페', openGame, MENU_ICON, 'html');
  await Risuai.addRisuScriptHandler('input', () => {
    try {
      if (S && S.settings.chatE > 0) {
        const got = addEnergy(S.settings.chatE + D('lamp'), false);
        if (got > 0) {
          if (visible) { renderTop(); toast(`채팅 보너스 <span class="mc-mini">${UI.bolt}+${got}</span>`); }
          else S.chatBonus += got;
          save();
        }
      }
    } catch (_) { }
    return null;
  });
  await Risuai.onUnload(async () => { await flush(); });
  try { document.addEventListener('visibilitychange', () => { if (document.hidden) flush(); }); window.addEventListener('pagehide', () => flush()); } catch (_) { }
  console.log(TAG, 'loaded');
} catch (err) {
  console.log(TAG, 'boot error', err?.message || err);
}
